</div>
<style>
.manage-page{max-width:980px;margin:0 auto;padding:1.5rem 1rem 3rem}.manage-shell{max-width:860px;margin:0 auto}.manage-header{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:1.4rem}.manage-header h1{font-size:2.1rem;line-height:1.1;margin:0 0 .5rem}.manage-header p{margin:0;color:var(--text-color-3,#8a8a8a);font-size:1rem}.back-link{display:inline-flex;align-items:center;justify-content:center;padding:.55rem .95rem;border-radius:999px;border:1px solid rgba(127,127,127,.18);background:rgba(255,255,255,.05);white-space:nowrap}.auth-card,.section-card,.item-card{background:var(--card-bg-color,#111);border:1px solid rgba(127,127,127,.14);border-radius:18px;box-shadow:0 8px 30px rgba(0,0,0,.04)}.auth-card{padding:1rem 1rem 1.1rem;margin-bottom:1rem}.auth-row{display:flex;gap:.75rem;align-items:center}.auth-row input{flex:1;min-width:0;border:1px solid rgba(127,127,127,.18);border-radius:999px;padding:.7rem 1rem;background:transparent;color:inherit;outline:none}.auth-row input:focus{border-color:var(--btn-bg-color,#1e80ff)}#loginBtn,.delete-btn{border:0;border-radius:999px;padding:.6rem 1rem;cursor:pointer;background:var(--btn-bg-color,#1e80ff);color:#fff;font-weight:600}.status-text{margin:.75rem 0 0;color:var(--text-color-3,#8a8a8a);font-size:.9rem}.section-card{padding:1rem;margin-top:1rem}.section-title-row{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:.9rem}.section-title-row h2{margin:0;font-size:1.3rem}.section-title-row span{color:var(--text-color-3,#8a8a8a);font-size:.9rem}.timeline{position:relative;padding-left:1.8rem}.timeline::before{content:"";position:absolute;left:.52rem;top:0;bottom:0;width:1px;background:rgba(127,127,127,.18)}.item{position:relative;margin-bottom:1rem;padding-left:.8rem}.item::before{content:"";position:absolute;left:-.16rem;top:1rem;width:.7rem;height:.7rem;border-radius:50%;background:var(--accent-color,#f1b34d);box-shadow:0 0 0 5px rgba(241,179,77,.12)}.item-card{padding:1rem 1.05rem}.item-head{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:.65rem;color:var(--text-color-3,#8a8a8a);font-size:.9rem}.item-meta{display:flex;flex-wrap:wrap;gap:.5rem;font-size:.85rem;color:var(--text-color-3,#8a8a8a)}.item-body{display:grid;gap:.85rem}.item-image{width:100%;max-height:420px;object-fit:cover;border-radius:14px;border:1px solid rgba(127,127,127,.12);background:rgba(0,0,0,.08)}.item-text{white-space:pre-wrap;word-break:break-word;line-height:1.9;font-size:1rem}.item-actions{display:flex;justify-content:flex-end;gap:.5rem;margin-top:.8rem;flex-wrap:wrap}.delete-btn{background:rgba(255,82,82,.1);color:#ff5f5f}.empty{padding:2rem 1rem;text-align:center;color:var(--text-color-3,#8a8a8a)}@media (max-width:640px){.manage-page{padding:1rem .8rem 2rem}.manage-header{align-items:flex-start;flex-direction:column}.auth-card,.section-card,.item-card{border-radius:16px}.auth-row{flex-direction:column;align-items:stretch}#loginBtn,.back-link{width:100%}.timeline{padding-left:1.35rem}}
