<script type="module">
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
const SUPABASE_URL = 'https://eqkcyfkhnihdchmcfdcw.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_4Y_S9gtbbOoa99cPZsKEbg_gaIw1GPW';
const ADMIN_EMAIL = '1557754391@qq.com';
const COMMENTS_TABLE = 'comments';
const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } });
const emailInput = document.getElementById('emailInput');
const loginBtn = document.getElementById('loginBtn');
const statusText = document.getElementById('statusText');
const notesList = document.getElementById('notesList');
const messagesList = document.getElementById('messagesList');
const setStatus = (text) => { statusText.textContent = text; };
const getSession = async () => { const { data } = await supabase.auth.getSession(); return data.session || null; };
const isAdmin = (session) => Boolean(session?.user?.email && session.user.email.toLowerCase() === ADMIN_EMAIL.toLowerCase());
const formatTime = (value) => new Date(value).toLocaleString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
const escapeText = (value) => (value || '').trim();
const resolveImageUrl = async (value) => {
  if (!value) return '';
  if (/^(https?:|data:)/i.test(value)) return value;
  if (value.startsWith('storage:')) {
    const storagePath = value.slice('storage:'.length);
    const { data, error } = await supabase.storage.from('thoughts-images').createSignedUrl(storagePath, 60 * 60 * 24 * 7);
    if (!error && data?.signedUrl) return data.signedUrl;
  }
  return value;
};
const renderNotes = async () => {
  const { data, error } = await supabase.from(COMMENTS_TABLE).select('id, content, website, created_at').eq('scope', 'notes').in('thread_key', ['notes', '/notes']).is('parent_id', null).order('created_at', { ascending: false });
  if (error) { notesList.innerHTML = `<div class="empty">加载失败：${error.message}</div>`; return; }
  if (!data.length) { notesList.innerHTML = '<div class="empty">还没有碎碎念。</div>'; return; }
  const resolved = await Promise.all(data.map(async (item) => ({ ...item, imageSrc: await resolveImageUrl(item.website) })));
  notesList.innerHTML = resolved.map((item) => `<article class="item" data-id="${item.id}"><div class="item-card"><div class="item-head"><time>${formatTime(item.created_at)}</time><span>碎碎念</span></div><div class="item-body">${item.imageSrc ? `<img class="item-image" src="${item.imageSrc}" alt="碎碎念图片">` : ''}<div class="item-text"></div></div><div class="item-actions"><button class="delete-btn" type="button" data-delete-note="${item.id}">删除</button></div></div></article>`).join('');
  notesList.querySelectorAll('.item').forEach((card) => { const item = resolved.find((entry) => entry.id === card.dataset.id); card.querySelector('.item-text').textContent = item.content; });
};
const renderMessages = async () => {
  const { data, error } = await supabase.from(COMMENTS_TABLE).select('id, name, content, created_at').eq('scope', 'board').is('parent_id', null).order('created_at', { ascending: false });
  if (error) { messagesList.innerHTML = `<div class="empty">加载失败：${error.message}</div>`; return; }
  if (!data.length) { messagesList.innerHTML = '<div class="empty">还没有留言。</div>'; return; }
  messagesList.innerHTML = data.map((item) => `<article class="item" data-id="${item.id}"><div class="item-card"><div class="item-head"><time>${formatTime(item.created_at)}</time><span>${escapeText(item.name) || '匿名'}</span></div><div class="item-text"></div><div class="item-actions"><button class="delete-btn" type="button" data-delete-message="${item.id}">删除</button></div></div></article>`).join('');
  messagesList.querySelectorAll('.item').forEach((card) => { const item = data.find((entry) => entry.id === card.dataset.id); card.querySelector('.item-text').textContent = item.content; });
};
const renderAll = async () => { await renderNotes(); await renderMessages(); };
const login = async () => {
  const email = emailInput.value.trim();
  if (!email) { setStatus('请输入邮箱。'); return; }
  loginBtn.disabled = true;
  setStatus('正在发送登录链接…');
  const redirectTo = `${window.location.origin}/notes/manage/`;
  const { error } = await supabase.auth.signInWithOtp({ email, options: { emailRedirectTo: redirectTo } });
  if (error) setStatus(`发送失败：${error.message}`); else setStatus('已发送登录链接，请查看邮箱。');
  loginBtn.disabled = false;
};
const removeNote = async (id) => { const session = await getSession(); if (!isAdmin(session)) { setStatus('只有管理员邮箱登录后才能删除。'); return; } if (!window.confirm('确定删除这条碎碎念吗？')) return; const { error } = await supabase.from(COMMENTS_TABLE).delete().eq('id', id); if (error) setStatus(`删除失败：${error.message}`); else { setStatus('已删除碎碎念'); await renderAll(); } };
const removeMessage = async (id) => { const session = await getSession(); if (!isAdmin(session)) { setStatus('只有管理员邮箱登录后才能删除。'); return; } if (!window.confirm('确定删除这条留言吗？')) return; const { error } = await supabase.from(COMMENTS_TABLE).delete().eq('id', id); if (error) setStatus(`删除失败：${error.message}`); else { setStatus('已删除留言'); await renderAll(); } };
notesList.addEventListener('click', (event) => { const target = event.target.closest('[data-delete-note]'); if (!target) return; removeNote(target.dataset.deleteNote); });
messagesList.addEventListener('click', (event) => { const target = event.target.closest('[data-delete-message]'); if (!target) return; removeMessage(target.dataset.deleteMessage); });
loginBtn.addEventListener('click', login);
setStatus('等待登录');
renderAll();
</script>

