<div class="messages-page">
  <div class="messages-shell">
    <header class="messages-header">
      <div>
        <h1>留言板</h1>
        <p>留下一点足迹、想法或问候。</p>
      </div>
    </header>

    <section class="composer-card">
      <div class="composer-grid single-field">
        <input id="nameInput" class="field" type="text" maxlength="24" placeholder="名称（必填）" />
      </div>
      <textarea id="messageInput" class="message-input" maxlength="1200" placeholder="既然来了，不妨留个言再走吧…"></textarea>
      <div class="composer-footer"><span id="countHint">0 / 1200</span><button type="button" id="sendBtn">提交留言</button></div>
      <p id="statusText" class="status-text">加载中…</p>
    </section>

    <section class="list-title">大家在聊</section>
    <section id="messagesList" class="messages-list"></section>
  </div>
</div>
<style>
.messages-page{max-width:980px;margin:0 auto;padding:1.5rem 1rem 3rem}.messages-shell{max-width:860px;margin:0 auto}.messages-header{margin-bottom:1.4rem}.messages-header h1{font-size:2.2rem;line-height:1.1;margin:0 0 .5rem}.messages-header p{margin:0;color:var(--text-color-3,#8a8a8a);font-size:1rem}.composer-card,.message-card{background:var(--card-bg-color,#111);border:1px solid rgba(127,127,127,.14);border-radius:18px;box-shadow:0 8px 30px rgba(0,0,0,.04)}.composer-card{padding:1rem 1rem 1.1rem}.composer-grid{display:grid;grid-template-columns:1fr;gap:.75rem;margin-bottom:.85rem}.field,.message-input{border:1px solid rgba(127,127,127,.18);border-radius:14px;background:transparent;color:inherit;outline:none;width:100%}.field{padding:.8rem .85rem}.message-input{min-height:180px;resize:vertical;padding:.95rem .95rem;line-height:1.75}.field:focus,.message-input:focus{border-color:var(--btn-bg-color,#1e80ff)}.composer-footer{display:flex;align-items:center;justify-content:space-between;gap:.75rem;margin-top:.8rem}#sendBtn,.delete-btn{border:0;border-radius:999px;padding:.6rem 1rem;cursor:pointer;transition:.2s ease}#sendBtn{background:var(--btn-bg-color,#1e80ff);color:#fff;font-weight:600}.status-text{margin:.75rem 0 0;color:var(--text-color-3,#8a8a8a);font-size:.9rem}.list-title{font-size:1.35rem;font-weight:700;margin:1.5rem 0 1rem}.messages-list{display:grid;gap:1rem}.message-card{padding:1rem}.message-top{display:flex;gap:.8rem;align-items:flex-start}.avatar{width:46px;height:46px;border-radius:50%;object-fit:cover;background:rgba(255,255,255,.08);flex:0 0 auto}.message-main{flex:1;min-width:0}.message-meta{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:.35rem;font-size:.95rem}.message-name{font-weight:700}.message-time{color:var(--text-color-3,#8a8a8a);font-size:.85rem}.message-text{white-space:pre-wrap;word-break:break-word;line-height:1.85;margin-top:.35rem}.message-actions{display:flex;justify-content:flex-end;gap:.5rem;margin-top:.8rem}.note-empty{padding:2rem 1rem;text-align:center;color:var(--text-color-3,#8a8a8a)}@media (max-width:760px){.composer-footer{flex-direction:column;align-items:stretch}#sendBtn{width:100%}}
</style>
<script type="module">
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
const SUPABASE_URL = 'https://eqkcyfkhnihdchmcfdcw.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_4Y_S9gtbbOoa99cPZsKEbg_gaIw1GPW';
const ADMIN_EMAIL = '1557754391@qq.com';
const COMMENTS_TABLE = 'comments';
const THREAD_KEY = 'board';
const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } });
const nameInput = document.getElementById('nameInput');
const messageInput = document.getElementById('messageInput');
const sendBtn = document.getElementById('sendBtn');
const statusText = document.getElementById('statusText');
const countHint = document.getElementById('countHint');
const messagesList = document.getElementById('messagesList');
const avatarPalette = ['#4F46E5','#0EA5E9','#10B981','#F59E0B','#EF4444','#8B5CF6','#EC4899','#14B8A6'];
const setStatus = (text) => statusText.textContent = text;
const count = () => { countHint.textContent = `${messageInput.value.length} / 1200`; };
const formatTime = (value) => new Date(value).toLocaleString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
const safeText = (value) => (value || '').trim();
const getSession = async () => { const { data } = await supabase.auth.getSession(); return data.session || null; };
const isAdmin = (session) => Boolean(session?.user?.email && session.user.email.toLowerCase() === ADMIN_EMAIL.toLowerCase());
const hashText = (value) => Array.from(String(value || '')).reduce((hash, char) => ((hash << 5) - hash + char.charCodeAt(0)) | 0, 0);
const avatarSvg = (label, seed) => {
  const index = Math.abs(hashText(seed)) % avatarPalette.length;
  const bg = avatarPalette[index];
  const letter = (label || 'A').trim().slice(0,1).toUpperCase();
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96" viewBox="0 0 96 96"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="${bg}"/><stop offset="100%" stop-color="#111827"/></linearGradient></defs><rect width="96" height="96" rx="48" fill="url(#g)"/><text x="48" y="58" text-anchor="middle" font-family="Arial, sans-serif" font-size="40" font-weight="700" fill="white">${letter}</text></svg>`;
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
};
const render = async () => {
  const { data, error } = await supabase.from(COMMENTS_TABLE).select('id, name, content, created_at').eq('scope', 'board').eq('thread_key', THREAD_KEY).is('parent_id', null).order('created_at', { ascending: false });
  if (error) { messagesList.innerHTML = `<div class="note-empty">加载失败：${error.message}</div>`; return; }
  const session = await getSession();
  const admin = isAdmin(session);
  if (!data.length) { messagesList.innerHTML = '<div class="note-empty">还没有留言，来做第一个吧。</div>'; return; }
  messagesList.innerHTML = data.map(item => `<article class="message-card" data-id="${item.id}"><div class="message-top"><img class="avatar" src="${avatarSvg(item.name, item.id)}" alt="头像" /><div class="message-main"><div class="message-meta"><div class="message-name">${item.name || '匿名'}</div><div class="message-time">${formatTime(item.created_at)}</div></div><div class="message-text"></div>${admin ? `<div class="message-actions"><button class="delete-btn" type="button" data-delete="${item.id}">删除</button></div>` : ''}</div></div></article>`).join('');
  messagesList.querySelectorAll('.message-card').forEach(card => { const item = data.find(entry => entry.id === card.dataset.id); card.querySelector('.message-text').textContent = item.content; });
};
const submit = async () => {
  const name = safeText(nameInput.value);
  const content = safeText(messageInput.value);
  if (!name || !content) { setStatus('名称和留言内容都要填写。'); return; }
  sendBtn.disabled = true; setStatus('正在提交…');
  const { error } = await supabase.from(COMMENTS_TABLE).insert({ scope: 'board', thread_key: THREAD_KEY, parent_id: null, name, content });
  if (error) setStatus(`提交失败：${error.message}`);
  else { nameInput.value=''; messageInput.value=''; count(); setStatus('已提交'); await render(); }
  sendBtn.disabled = false;
};
const remove = async (id) => { const session = await getSession(); if (!isAdmin(session)) { setStatus('只有管理员邮箱登录后才能删除。'); return; } if (!window.confirm('确定删除这条留言吗？')) return; const { error } = await supabase.from(COMMENTS_TABLE).delete().eq('id', id); if (error) setStatus(`删除失败：${error.message}`); else { setStatus('已删除'); await render(); } };
messagesList.addEventListener('click', (event) => { const target = event.target.closest('[data-delete]'); if (!target) return; remove(target.dataset.delete); });
sendBtn.addEventListener('click', submit); messageInput.addEventListener('input', count); messageInput.addEventListener('keydown', (event) => { if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') submit(); });
count(); setStatus('欢迎留言'); render();
</script>

